            else:
                print(f"[{i}] MSG {role}: {str(content)[:300]}")
        elif t == 'customType':
            data = o.get('data',{})
            if isinstance(data, dict):
                d = data.get('type','?')
                if d == 'tool_result':
                    rc = data.get('content','')
