import json
fn='/home/halei/.openclaw/agents/tts/sessions/236e682a-4f16-460b-88bd-3595ca024543.jsonl'
with open(fn) as f:
    lines = f.readlines()
print(f'Lines: {len(lines)}')
for i, l in enumerate(lines):
    try:
        o = json.loads(l)
        t = o.get('type','?')
        ts = o.get('timestamp','')[:19]
        if t == 'session':
            print(f"[{i}] SESSION start, cwd={o.get('cwd')}")
        elif t == 'model_change':
            print(f"[{i}] MODEL: {o.get('provider')}/{o.get('modelId')}")
        elif t == 'thinking_level_change':
            print(f"[{i}] THINK: {o.get('thinkingLevel')}")
        elif t == 'message':
            msg = o.get('message',{})
            role = msg.get('role','?')
            content = msg.get('content','')
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get('type')=='text':
                        txt = c.get('text','')
                        print(f"[{i}] MSG {role}: {txt[:300]}")
                        break
                    if isinstance(c, dict) and c.get('type')=='tool_use':
                        print(f"[{i}] MSG {role}: TOOL_USE {c.get('name')} input={str(c.get('input',{}))[:200]}")
            else:
                print(f"[{i}] MSG {role}: {str(content)[:300]}")
        elif t == 'customType':
            data = o.get('data',{})
            if isinstance(data, dict):
                d = data.get('type','?')
                if d == 'tool_result':
                    rc = data.get('content','')
                    if isinstance(rc, list):
                        for c in rc:
                            if isinstance(c, dict) and c.get('type')=='text':
                                print(f"[{i}] TOOL_RESULT: {c.get('text','')[:300]}")
                                break
                    else:
                        print(f"[{i}] TOOL_RESULT: {str(rc)[:300]}")
        else:
            print(f"[{i}] {t}")
    except Exception as e:
        print(f"[{i}] ERR {e}")
EOF

