echo "---tts latest session headers (按时间倒序，前10)---"
cd /home/halei/.openclaw/agents/tts/sessions/
ls -lt --time=mtime *.jsonl 2>/dev/null | head -10
echo ""
echo "---6月4日 session 头部---"
ls -lt --time=mtime 6月* 09517b56-0fb1-4c70-8a74-7b5bbd501f0d.jsonl 2>/dev/null
ls -la 09517b56-0fb1-4c70-8a74-7b5bbd501f0d.jsonl 2>/dev/null
head -3 09517b56-0fb1-4c70-8a74-7b5bbd501f0d.jsonl 2>/dev/null
echo "---6月4日 session 模型/最后消息---"
python3 -c "
import json
fn='/home/halei/.openclaw/agents/tts/sessions/09517b56-0fb1-4c70-8a74-7b5bbd501f0d.jsonl'
try:
    with open(fn) as f:
        lines = f.readlines()
    print(f'Lines: {len(lines)}')
    for i,l in enumerate(lines[:3]):
        try:
            o=json.loads(l)
            print(f'--- line {i} keys: {list(o.keys())[:8]}')
            if 'model' in o: print('model:', o.get('model'))
            if 'role' in o: print('role:', o.get('role'))
            content = o.get('content','')
            if isinstance(content, str):
                print('content[:300]:', content[:300])
            else:
                print('content type:', type(content).__name__)
        except Exception as e:
            print(f'line {i} parse err: {e}')
    # 找最后一条带 role 的
    print('=== last lines ===')
    for l in lines[-3:]:
        try:
            o=json.loads(l)
            print('---', list(o.keys())[:8])
            if 'role' in o: print('role:', o.get('role'))
            if 'model' in o: print('model:', o.get('model'))
            content = o.get('content','')
            if isinstance(content, str):
                print('content[-400:]:', content[-400:])
        except: pass
except Exception as e:
    print('ERR:', e)
"

